/**
 * loadBundle.js — the contractual interface with the analytical pipeline.
 *
 * The bundle (schema v1.0.0) is generated by NB06 in amoc-thesis-pipeline.
 * Everything perceivable in Living Atlantic must be traceable to a field
 * in this file. That traceability is the design criterion of the thesis
 * (Ch. 7): no decorative data, no invented values.
 *
 * Non-finite values are serialized as null — filter them where relevant.
 */

import { extent } from 'd3-array';

const BUNDLE_URL = `${import.meta.env.BASE_URL}data/amoc_translate_bundle.json`;
const EXPECTED_SCHEMA = '1.0.0';

export async function loadBundle() {
  const res = await fetch(BUNDLE_URL);
  if (!res.ok) throw new Error(`Bundle fetch failed: ${res.status}`);
  const bundle = await res.json();

  if (bundle.meta?.schema_version !== EXPECTED_SCHEMA) {
    console.warn(
      `Bundle schema ${bundle.meta?.schema_version} ≠ expected ${EXPECTED_SCHEMA}. ` +
      'Re-check field names against the README before trusting mappings.'
    );
  }

  return {
    raw: bundle,

    // --- Scena III: the engine room -------------------------------------
    trajectory: {
      time: bundle.trajectory_monthly.time,          // "YYYY-MM", index-aligned
      pc1: bundle.trajectory_monthly.pc1,
      pc2: bundle.trajectory_monthly.pc2,
      n: bundle.trajectory_monthly.time.length,
    },
    cloud: {
      pc1: bundle.manifold_cloud.pc.pc1.filter(Number.isFinite),
      pc2: bundle.manifold_cloud.pc.pc2.filter(Number.isFinite),
    },

    // --- Scena II: the physical column ----------------------------------
    pca: {
      depth: bundle.pca.depth_m,
      eof1: bundle.pca.eof1,
      eof2: bundle.pca.eof2,
      varExplained: bundle.pca.var_explained,
      // profile(t) ≈ mean + pc1(t)·eof1 + pc2(t)·eof2  (Sv)
      // NOTE: the bundle ships EOFs but not the mean profile; if Scena II
      // needs absolute Sv values, export `mean_profile` from NB06 (one line).
    },

    // --- Scena IV: the scar ----------------------------------------------
    anomalies: {
      clusters: bundle.anomalies.clusters,           // rank 0 = 2009-2010
      flagged: bundle.anomalies.flagged_points,
    },

    // --- Scena V: the threshold -------------------------------------------
    ensemble: bundle.copernicus_ensemble,

    // Pre-computed extents so every scene shares one coordinate system.
    extents: {
      pc1: extent([
        ...bundle.manifold_cloud.pc.pc1.filter(Number.isFinite),
        ...bundle.trajectory_monthly.pc1.filter(Number.isFinite),
      ]),
      pc2: extent([
        ...bundle.manifold_cloud.pc.pc2.filter(Number.isFinite),
        ...bundle.trajectory_monthly.pc2.filter(Number.isFinite),
      ]),
    },
  };
}
